const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',menu:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',bag:'M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',left:'m14 5-7 7 7 7',right:'m10 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',store:'M3 10v11h18V10M2 10l2-7h16l2 7M2 10c0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0M9 21v-7h6v7',truck:'M2 5h12v12H2zM14 10h4l4 5v2h-8M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM20 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 6v6l4 2',check:'m5 12 4 4L20 5',receipt:'M5 2v20l3-2 4 2 4-2 3 2V2l-3 2-4-2-4 2-3-2ZM8 8h8M8 12h8M8 16h5',gift:'M3 8h18v5H3zM5 13v8h14v-8M12 8v13M12 8C3 9 4 0 8 3l4 5Zm0 0c9 1 8-8 4-5l-4 5'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.menu}"/></svg>`;
const fa=n=>Number(n).toLocaleString('fa-IR');const money=n=>`<span class="price">${fa(n)}<small>تومان</small></span>`;
const products=[{id:1,name:'برگر نوستالژی',cat:'برگر',img:'burger.jpg',price:645000,desc:'۱۵۰ گرم گوشت، سس مخصوص، گوجه، خیارشور و ریحان',special:true,star:'۴٫۹'},{id:2,name:'پیتزا مخصوص آبی‌بی',cat:'پیتزا',img:'pizza.jpg',price:1098000,desc:'ژامبون گوشت، گوشت چرخ‌کرده، قارچ و پنیر پیتزا',special:true,star:'۴٫۸'},{id:3,name:'سیب‌زمینی با ادویه',cat:'پیش‌غذا',img:'fries.jpg',price:398000,desc:'سیب‌زمینی برشته با ادویه مخصوص',special:true,star:'۴٫۸'},{id:4,name:'املت',cat:'صبحانه',img:'breakfast.jpg',price:398000,desc:'سس گوجه مخصوص، ۳ عدد تخم‌مرغ، نان سنگک، سالاد و سیب‌زمینی',special:true,star:'۴٫۹'},{id:5,name:'قارچ برگر',cat:'برگر',img:'mushroom-burger.jpg',price:695000,desc:'۱۵۰ گرم گوشت، قارچ، سس مخصوص و ریحان',star:'۴٫۹'},{id:6,name:'پیتزا پپرونی',cat:'پیتزا',img:'pepperoni.jpg',price:928000,desc:'پپرونی، قارچ، هالوپینو، پنیر و سس تند',star:'۴٫۷'},{id:7,name:'سیب‌زمینی ویژه',cat:'پیش‌غذا',img:'special-fries.jpg',price:645000,desc:'سیب‌زمینی، ژامبون، قارچ و پنیر پیتزا',star:'۴٫۸'},{id:8,name:'پیتزا مرغ و قارچ',cat:'پیتزا',img:'chicken-pizza.jpg',price:995000,desc:'مرغ طعم‌دارشده، قارچ و پنیر پیتزا',star:'۴٫۸'}];
const branches=[{id:4,name:'شعبه کسایی',area:'کسایی',type:'صبحانه، ساندویچ و پیتزا',hours:'۷:۳۰ تا ۱۱:۴۵ · ۱۲:۳۰ تا ۱۵ · ۱۷ تا ۲:۳۰'},{id:9,name:'اغذیه فلکه گاز',area:'فلکه گاز',type:'ساندویچ و پیش‌غذا',hours:'ساعت فعالیت در نسخه نهایی تکمیل می‌شود'},{id:12,name:'پیتزای فلکه گاز',area:'فلکه گاز',type:'پیتزا و پیش‌غذا',hours:'ساعت فعالیت در نسخه نهایی تکمیل می‌شود'}];
let state={page:'splash',branch:null,mode:'delivery',cat:'همه',query:'',cart:[],favorites:[],slide:0,order:null};
try{state.cart=JSON.parse(sessionStorage.getItem('abibiCart')||'[]');state.favorites=JSON.parse(localStorage.getItem('abibiFav')||'[]');state.branch=branches.find(b=>b.id===Number(sessionStorage.getItem('abibiBranch')))||null}catch{}
try{state.order=JSON.parse(sessionStorage.getItem('abibiOrder')||'null')}catch{}
state.checkoutDraft={};
let sliderPaused=false,focusBeforeModal=null,toastTimer,slideTimer;const count=()=>state.cart.reduce((n,x)=>n+x.qty,0),sum=()=>state.cart.reduce((n,x)=>n+(products.find(p=>p.id===x.id).price+x.extra)*x.qty,0);const save=()=>{sessionStorage.setItem('abibiCart',JSON.stringify(state.cart));if(state.branch)sessionStorage.setItem('abibiBranch',state.branch.id)};
const brand=()=>`<span class="brand"><img src="assets/logo.webp" alt="شخصیت آبی‌بی" onerror="this.style.display='none'"><span><strong>آبی‌بی</strong><small>ABIBI FOOD</small></span></span>`;
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function go(page,fromHistory=false){closeModal();if(!state.branch&&!['branches','splash'].includes(page))page='branches';if(page==='checkout'&&!count())page='cart';state.page=page;if(!fromHistory&&location.hash!=='#'+page){if(['splash','branches'].includes(page))history.replaceState(null,'','#'+page);else history.pushState(null,'','#'+page)}render();window.scrollTo(0,0)}
function setMode(mode){captureDraft();state.mode=mode;render()}
function selectBranch(id){const b=branches.find(x=>x.id===id);if(state.branch&&state.branch.id!==id&&count()){openModal(`<div class="modal-small"><h2>تغییر شعبه؟</h2><p>منو و موجودی هر شعبه متفاوت است. با انتخاب ${b.name}، سبد فعلی پاک می‌شود.</p><button class="btn full" data-action="confirmBranch" data-id="${id}">تغییر شعبه و پاک‌کردن سبد</button><button class="btn light full" style="margin-top:10px" data-action="close">ادامه با شعبه فعلی</button></div>`);return}state.branch=b;save();go('home')}
function header(){return `<div class="headerwrap"><header class="topbar"><button data-action="go" data-page="home" aria-label="خانه آبی‌بی">${brand()}</button><nav class="desktop-nav" aria-label="ناوبری اصلی">${[['home','خانه'],['menu','منوی غذا'],['orders','سفارش‌های من']].map(([p,t])=>`<button class="${state.page===p?'active':''}" data-action="go" data-page="${p}">${t}</button>`).join('')}</nav><button class="branch-btn" data-action="go" data-page="branches">${icon('pin')}<span><small>شعبه انتخاب‌شده</small><strong>${state.branch.name}</strong></span>${icon('left')}</button><div class="top-actions"><button class="icon user-btn" aria-label="حساب من" data-action="go" data-page="account">${icon('user')}</button><button class="icon bag" aria-label="سبد خرید" data-action="go" data-page="cart">${icon('bag')}${count()?`<span class="badge">${fa(count())}</span>`:''}</button></div></header><div class="demo">نسخه نمایشی برای بررسی طراحی · امکانات فروش آزمایشی‌اند · سفارش واقعی ثبت نمی‌شود</div></div>`}
function nav(){return `<nav class="mobile-nav" aria-label="ناوبری موبایل">${[['home','home','خانه'],['menu','menu','منوی غذا'],['orders','receipt','سفارش‌ها'],['account','user','حساب من']].map(([p,i,t])=>`<button data-action="go" data-page="${p}" class="${state.page===p?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>${count()&&['home','menu'].includes(state.page)?`<button class="mobile-cart" data-action="go" data-page="cart"><span><span class="count">${fa(count())}</span>مشاهده سبد خرید</span><span class="row">${money(sum())}${icon('left')}</span></button>`:''}`}
const footer=()=>`<footer class="footer">${brand()}<span>با طعم آبی‌بی، یه دل سیر خاطره.</span><span>طراحی و توسعه سُها سیستم</span></footer>`;
const modeSwitch=()=>`<div class="segmented"><button class="${state.mode==='delivery'?'active':''}" data-action="mode" data-mode="delivery">${icon('truck')}ارسال با پیک</button><button class="${state.mode==='pickup'?'active':''}" data-action="mode" data-mode="pickup">${icon('store')}تحویل حضوری</button></div>`;
function branchPage(){return `<div class="branches fade-in"><section class="branch-story">${brand()}<h2>یه دل سیر خاطره.</h2><p>طعم آشنای آبی‌بی، این بار هر جا که تویی.</p><span class="story-bottom">GOOD FOOD. GOOD MEMORIES.</span></section><section class="branch-content"><div class="eyebrow">WELCOME TO ABIBI</div><h1>از کدوم شعبه سفارش می‌دی؟</h1><p>شعبه‌ات رو انتخاب کن تا بریم سراغ خوشمزه‌ها.</p>${branches.map((b,i)=>`<button class="branch-card" data-action="branch" data-id="${b.id}"><span class="branch-art">${icon('store')}</span><span class="info"><h3>${b.name}</h3><p>${b.type}</p><span class="pill tag">${icon('pin')}${b.area}</span></span><span class="icon">${icon('left')}</span></button>`).join('')}<div class="branch-foot">${icon('clock')} اطلاعات ارسال و ساعت فعالیت در مرحله اتصال به شعبه تکمیل می‌شود.</div><div class="notice">نسخه نمایشی طراحی · منوهای شعبه‌ها در این نمونه مشترک‌اند.</div></section></div>`}
const cats=[['همه','menu','burger.jpg'],['برگر','menu','burger.jpg'],['پیتزا','menu','pizza.jpg'],['صبحانه','menu','breakfast.jpg'],['پیش‌غذا','menu','fries.jpg']];
function categories(home=false){return `<div class="cats ${!home?'menu-cats':''}" aria-label="دسته‌بندی غذاها">${cats.map(([c,i,img])=>`<button class="cat ${!home&&state.cat===c?'active':''}" data-action="cat" data-cat="${c}"><img src="assets/${img}" alt=""><span>${c==='همه'?'همه غذاها':c}</span></button>`).join('')}</div>`}
function card(p,special=false){const q=state.cart.filter(x=>x.id===p.id).reduce((a,b)=>a+b.qty,0);return `<article class="card">${special?'<span class="label">پیشنهاد آبی‌بی</span>':''}<button class="heart ${state.favorites.includes(p.id)?'saved':''}" data-action="fav" data-id="${p.id}" aria-label="علاقه‌مندی ${p.name}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button><button class="card-image" data-action="detail" data-id="${p.id}" aria-label="جزئیات ${p.name}"><img loading="lazy" src="assets/${p.img}" alt="${p.name}"></button><div class="card-body"><h3><button data-action="detail" data-id="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="row between">${money(p.price)}${q?`<div class="qty"><button data-action="add" data-id="${p.id}" aria-label="افزودن ${p.name}">+</button><span>${fa(q)}</span><button data-action="minus" data-id="${p.id}" aria-label="کاهش ${p.name}">−</button></div>`:`<button class="add" data-action="add" data-id="${p.id}" aria-label="افزودن ${p.name}">+</button>`}</div></div></article>`}
const slides=[{over:'خوشمزه‌های آبی‌بی',title:'یه گاز خوشمزه،<br><em>یه عالمه خاطره!</em>',sub:'برگرهای آبی‌بی منتظر انتخاب تو هستن.',cta:'برگرمو انتخاب می‌کنم',cat:'برگر',img:'burger.jpg'},{over:'وقت یه دورهمی خوشمزه‌ست',title:'همه دور هم،<br><em>پیتزا وسط!</em>',sub:'از مخصوص آبی‌بی تا پپرونیِ تند و جذاب.',cta:'بریم سراغ پیتزا',cat:'پیتزا',img:'pizza.jpg'},{over:'شروع خوب روز',title:'صبح بخیر،<br><em>با طعم آبی‌بی.</em>',sub:'یه صبحانه گرم برای شروع یه روز تازه.',cta:'دیدن صبحانه‌ها',cat:'صبحانه',img:'breakfast.jpg'}];
function hero(){const s=slides[state.slide];return `<section class="hero" id="hero" aria-label="پیشنهادهای تبلیغاتی"><div class="hero-copy"><div class="overline">— ${s.over}</div><h1>${s.title}</h1><p>${s.sub}</p><button class="btn" data-action="cat" data-cat="${s.cat}">${s.cta}${icon('left')}</button></div><img class="hero-food" src="assets/${s.img}" alt="${s.cat}"><span class="hero-note">یه دل سیر خاطره</span><button class="slider-pause" data-action="pauseSlider" aria-label="${sliderPaused?'ادامه پخش اسلایدر':'توقف پخش اسلایدر'}">${sliderPaused?'▶':'Ⅱ'}</button><div class="slide-controls">${slides.map((x,i)=>`<button aria-label="اسلاید ${i+1}" aria-pressed="${i===state.slide}" class="${i===state.slide?'active':''}" data-action="slide" data-id="${i}"></button>`).join('')}</div><div class="slide-arrows"><button data-action="prevslide" aria-label="اسلاید قبلی">${icon('right')}</button><button data-action="nextslide" aria-label="اسلاید بعدی">${icon('left')}</button></div></section>`}
function sectionTitle(t,sub,cat='همه'){return `<div class="section-head"><div class="section-title"><div><h2>${t}</h2><small>${sub}</small></div></div><button class="text-link" data-action="cat" data-cat="${cat}">مشاهده همه${icon('left')}</button></div>`}
function homePage(){return `<div class="subhead"><div><span class="crumb">خوش اومدی به آبی‌بی</span><div style="font-size:12px;font-weight:bold">امروز چی میل داری؟</div></div>${modeSwitch()}</div>${hero()}${categories(true)}${sectionTitle('پیشنهاد ویژه','چند انتخاب خوشمزه برای امروزت')}<div class="grid">${products.filter(p=>p.special).map(p=>card(p,true)).join('')}</div>${sectionTitle('پرفروش‌ترین‌ها','محبوب‌های منو · چیدمان نمایشی')}<div class="grid">${[products[4],products[5],products[1],products[6]].map(p=>card(p)).join('')}</div><div class="offer"><div class="row">${icon('gift')}<div><h3>کنار غذات، یه خوشمزه دیگه!</h3><p>پیش‌غذاها رو هم ببین؛ سفارشت کامل‌تر می‌شه.</p></div></div><button class="btn outline" data-action="cat" data-cat="پیش‌غذا">دیدن پیش‌غذاها</button></div>${footer()}`}
function title(t,sub=''){return `<div class="page-title"><button class="icon" data-action="go" data-page="home" aria-label="بازگشت به خانه">${icon('right')}</button><div><h1>${t}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div></div>`}
function cartSummary(checkout=false){return `<div class="total-row"><span>جمع سفارش (${fa(count())} مورد)</span>${money(sum())}</div><div class="total-row"><span>هزینه ارسال</span><span>${state.mode==='pickup'?'تحویل حضوری؛ بدون هزینه':checkout?'۳۵٬۰۰۰ تومان (نمونه)':'در مرحله تکمیل سفارش'}</span></div><div class="total-row final"><span>${checkout?'مبلغ نمایشی نهایی':'جمع غذاها'}</span>${money(sum()+(checkout&&state.mode==='delivery'?35000:0))}</div>`}
function miniCart(){return `<aside class="sidecart"><div class="row between"><h3>سبد خوشمزه‌های تو</h3>${icon('bag')}</div><p class="muted">${state.branch.name}</p>${!count()?`<div class="empty">${icon('bag')}<p>جای یه غذای خوشمزه خالیه!</p></div>`:`${state.cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="mini-item"><h4>${p.name}${x.extra?' + پنیر اضافه':''}</h4><div class="row between">${qty(i)}${money((p.price+x.extra)*x.qty)}</div></div>`}).join('')}${cartSummary()}<button class="btn full" data-action="go" data-page="cart">مشاهده سبد${icon('left')}</button>`}</aside>`}
function menuPage(){return `<div class="row between menu-top">${title('منوی آبی‌بی','انتخاب کن، اضافه کن، نوش جان!')}<label class="search">${icon('search')}<input id="search" type="search" placeholder="دنبال چی می‌گردی؟" aria-label="جست‌وجوی غذا" value="${esc(state.query)}"></label></div>${categories()}<div class="menu-layout"><section><div class="row between" style="margin-bottom:18px"><h3>${state.cat==='همه'?'همه خوشمزه‌ها':state.cat}</h3><span class="muted" id="result-count"></span></div><div class="grid" id="product-results">${menuResults()}</div></section>${miniCart()}</div>`}
function menuResults(){const normalize=t=>t.replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\s‌]+/g,'');const list=products.filter(p=>(state.cat==='همه'||state.cat===p.cat)&&normalize(p.name+' '+p.desc).includes(normalize(state.query))); return list.length?list.map(p=>card(p)).join(''):'<p class="no-results">غذایی پیدا نشد؛ نام دیگری جست‌وجو کن.</p>'}
function qty(i){const x=state.cart[i];return `<div class="qty"><button data-action="qty" data-id="${i}" data-delta="1" aria-label="افزایش تعداد">+</button><span>${fa(x.qty)}</span><button data-action="qty" data-id="${i}" data-delta="-1" aria-label="کاهش تعداد">−</button></div>`}
function cartPage(){return `${title('سبد خریدت',state.branch.name)}${!count()?`<div class="panel empty">${icon('bag')}<h3>سبدت هنوز خالیه</h3><p>از منوی آبی‌بی، خوشمزه موردعلاقه‌ات رو انتخاب کن.</p><button class="btn" data-action="go" data-page="menu">دیدن منوی غذا${icon('left')}</button></div>`:`<div class="cart-layout"><div><section class="panel">${state.cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-item"><img src="assets/${p.img}" alt="${p.name}"><div class="item-info"><h3>${p.name}</h3><p>${x.extra?'با پنیر اضافه':'سرو استاندارد'}${x.note?' · '+esc(x.note):''}</p>${qty(i)}</div><div class="end">${money((p.price+x.extra)*x.qty)}<br><button class="remove" data-action="remove" data-id="${i}">حذف</button></div></div>`}).join('')}</section><button class="text-link" data-action="go" data-page="menu">+ اضافه‌کردن غذا به سفارش</button><div class="notice">قیمت‌ها و امکانات این مسیر برای نمایش قالب‌اند و سفارش واقعی ایجاد نمی‌کنند.</div></div><aside class="sidecart"><h3>خلاصه سفارش</h3>${cartSummary()}<button class="btn full" data-action="go" data-page="checkout">ادامه سفارش${icon('left')}</button></aside></div>`}`}
function checkoutPage(){return `${title('تکمیل سفارش','فقط چند قدم تا یه غذای خوشمزه')}<form id="checkout-form"><div class="cart-layout"><div><section class="panel"><div class="step-label"><span>۱</span><h2>چطور سفارشت رو می‌گیری؟</h2></div>${modeSwitch()}<div class="notice">${state.mode==='delivery'?'آدرس زیر فقط در همین مرورگر برای نمایش مسیر استفاده می‌شود.':'تحویل از '+state.branch.name+' · آدرس دقیق شعبه در نسخه نهایی تکمیل می‌شود.'}</div></section><section class="panel"><div class="step-label"><span>۲</span><h2>مشخصات دریافت‌کننده</h2></div><div class="field-grid"><div class="field"><label for="customer">نام دریافت‌کننده</label><input id="customer" name="customer" required placeholder="نام و نام خانوادگی" autocomplete="name"></div><div class="field"><label for="phone">شماره موبایل</label><input id="phone" name="phone" type="tel" inputmode="tel" pattern="[0-9۰-۹٠-٩]{11}" required placeholder="۰۹۱۲۳۴۵۶۷۸۹" autocomplete="tel"></div></div>${state.mode==='delivery'?'<div class="field"><label for="address">آدرس تحویل</label><textarea id="address" name="address" required minlength="10" placeholder="خیابان، کوچه، پلاک و واحد"></textarea></div>':''}<div class="field"><label for="notes">توضیحات سفارش (اختیاری)</label><input id="notes" name="notes" placeholder="اگر نکته‌ای هست، اینجا بنویس"></div></section><section class="panel"><div class="step-label"><span>۳</span><h2>زمان دریافت</h2></div><label class="check-choice"><input type="radio" name="time" value="soon" checked><span><strong>اولین زمان ممکن</strong><p class="muted">حدود ۳۰ تا ۴۵ دقیقه · زمان نمونه</p></span></label><label class="check-choice"><input type="radio" name="time" value="later"><span><strong>زمان دلخواه</strong><p class="muted">انتخاب زمان برای نمایش قالب</p></span></label><div id="schedule-field" class="field" hidden><label for="schedule">زمان دریافت</label><input id="schedule" name="schedule" type="datetime-local"></div></section></div><aside class="sidecart"><h3>بازبینی سفارش</h3><p class="muted">${state.branch.name}</p>${state.cart.map(x=>`<div class="total-row"><span>${products.find(p=>p.id===x.id).name}</span><span>× ${fa(x.qty)}</span></div>`).join('')}${cartSummary(true)}<div class="notice">پرداخت آزمایشی است. مبلغی دریافت و پیامکی ارسال نمی‌شود.</div><button class="btn full" type="submit">ثبت سفارش نمایشی${icon('left')}</button></aside></div></form>`}
function successPage(){if(!state.order)return emptyOrders();return `${title('پیگیری سفارش')}<div class="success"><div class="success-hero"><div class="success-icon">${icon('check')}</div><span class="pill green">سفارش نمایشی</span><h1>سفارشت ثبت شد!</h1><p>این رسید آزمایشی است و به شعبه ارسال نشده است.</p><div class="row" style="justify-content:center;margin:20px"><span class="muted">شماره سفارش</span><strong style="letter-spacing:2px">AB-${state.order.number}</strong></div></div><section class="panel"><div class="row between"><h3>وضعیت سفارش</h3><span class="pill tag">پیش‌نمایش</span></div><div class="timeline">${[['check','ثبت سفارش','سفارش نمایشی با موفقیت ایجاد شد'],['store','آماده‌سازی در شعبه','در انتظار تأیید · مرحله نمایشی'],['truck',state.order.mode==='pickup'?'آماده تحویل حضوری':'ارسال با پیک','مرحله بعدی'],['bag','نوش جان!','تحویل سفارش']].map(([i,t,s],n)=>`<div class="${n===0?'done':''}"><span class="dot">${icon(i)}</span><span><strong>${t}</strong><p>${s}</p></span></div>`).join('')}</div></section><section class="panel"><div class="total-row"><span>شعبه</span><strong>${state.order.branch}</strong></div><div class="total-row"><span>تعداد غذاها</span><strong>${fa(state.order.count)}</strong></div><div class="total-row final"><span>مبلغ نمایشی</span>${money(state.order.total)}</div>${state.order.timing&&state.order.timing!=='soon'?`<div class="total-row"><span>زمان انتخاب‌شده</span><strong>${new Date(state.order.timing).toLocaleString('fa-IR')}</strong></div>`:''}</section>${state.order.items?`<button class="btn outline full" style="margin-bottom:12px" data-action="reorder">${icon('bag')}سفارش دوباره همین غذاها</button>`:''}<button class="btn full" data-action="go" data-page="home">بازگشت به خانه</button></div>`}
function emptyOrders(){return `${title('سفارش‌های من')}<div class="panel empty">${icon('receipt')}<h3>هنوز سفارشی نداری</h3><p>اولین سفارش نمایشی‌ات رو از منو شروع کن.</p><button class="btn" data-action="go" data-page="menu">مشاهده منو</button></div>`}
function accountPage(){return `${title('حساب من')}<div class="panel account-card"><div class="success-icon">${icon('user')}</div><h2>به آبی‌بی خوش اومدی</h2><p class="muted" style="margin:12px 0 25px">برای تجربه مسیر ورود، نسخه نمایشی را امتحان کن.</p><button class="btn full" data-action="login">ورود با شماره موبایل</button><p class="muted" style="margin-top:12px">ورود واقعی و ارسال پیامک در این نسخه فعال نیست.</p></div>${state.favorites.length?`${sectionTitle('علاقه‌مندی‌ها','انتخاب‌های خوشمزه تو')}<div class="grid">${products.filter(p=>state.favorites.includes(p.id)).map(p=>card(p)).join('')}</div>`:''}`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){clearInterval(slideTimer);document.body.style.overflow='';if(state.page==='splash'){document.getElementById('app').innerHTML=`<div class="splash">${brand()}<p>یه دل سیر خاطره.</p><div class="loading-line"></div><button class="skip" data-action="go" data-page="branches">ورود به آبی‌بی ←</button></div>`;return}if(state.page==='branches'){document.getElementById('app').innerHTML=branchPage();return}const pages={home:homePage,menu:menuPage,cart:cartPage,checkout:checkoutPage,success:successPage,orders:state.order?successPage:emptyOrders,account:accountPage};document.getElementById('app').innerHTML=header()+`<main class="container fade-in">${(pages[state.page]||homePage)()}</main>`+nav();if(state.page==='home'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){slideTimer=setInterval(()=>{if(!sliderPaused&&!document.hidden&&!document.querySelector('.modal-overlay'))changeSlide((state.slide+1)%slides.length)},6500)}bindForms()}
function changeSlide(n){state.slide=(n+slides.length)%slides.length;const el=document.getElementById('hero');if(el){el.outerHTML=hero();bindSwipe()}}
function bindSwipe(){const h=document.getElementById('hero');if(!h)return;let x;h.addEventListener('touchstart',e=>x=e.touches[0].clientX,{passive:true});h.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-x;if(Math.abs(d)>45)changeSlide(state.slide+(d>0?1:-1))},{passive:true})}
function add(id,extra=0,note=''){let x=state.cart.find(x=>x.id===id&&x.extra===extra&&x.note===note);if(x)x.qty++;else state.cart.push({id,qty:1,extra,note});save();render();toast('به سبد خوشمزه‌هات اضافه شد')}
function openModal(html){focusBeforeModal=document.activeElement;document.getElementById('modal').innerHTML=`<div class="modal-overlay"><section class="modal-box" role="dialog" aria-modal="true" aria-label="جزئیات و انتخاب‌های سفارش"><button class="close" data-action="close" aria-label="بستن">${icon('close')}</button>${html}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal-box button')?.focus()}
function closeModal(){document.getElementById('modal').innerHTML='';document.body.style.overflow='';focusBeforeModal?.focus();focusBeforeModal=null}
function detail(id){let p=products.find(p=>p.id===id);openModal(`<div class="detail"><img class="detail-image" src="assets/${p.img}" alt="${p.name}"><div class="detail-body"><span class="pill tag">${p.cat}</span><h2>${p.name}</h2><p>${p.desc}</p>${money(p.price)}<hr style="border:0;border-top:1px solid #e9dfd2;margin:20px 0"><h3 style="font-size:13px">سفارشت رو شخصی کن</h3><label><input id="extra-cheese" type="checkbox">پنیر اضافه <span class="muted">+ ۴۵٬۰۰۰ تومان</span></label><p class="muted">گزینه نمایشی؛ منوی نهایی با شعبه هماهنگ می‌شود.</p><div class="field" style="margin:14px 0 0"><input id="food-note" aria-label="توضیحات غذا" placeholder="توضیحی برای این غذا داری؟"></div><button class="btn full" data-action="detailAdd" data-id="${id}">افزودن به سبد${icon('bag')}</button></div></div>`)}
function captureDraft(){const f=document.getElementById('checkout-form');if(!f)return;for(const el of f.querySelectorAll('input,textarea')){if(el.name&&(el.type!=='radio'||el.checked))state.checkoutDraft[el.name]=el.value}}
function restoreDraft(){const f=document.getElementById('checkout-form');if(!f)return;for(const [name,value] of Object.entries(state.checkoutDraft)){const el=f.elements[name];if(el)el.value=value}const later=f.elements.time.value==='later';document.getElementById('schedule-field').hidden=!later;f.elements.schedule.required=later;f.addEventListener('input',captureDraft);f.addEventListener('change',captureDraft)}
function bindForms(){bindSwipe();restoreDraft();const search=document.getElementById('search');search?.addEventListener('input',e=>{state.query=e.target.value.trim();document.getElementById('product-results').innerHTML=menuResults()});document.querySelectorAll('input[name="time"]').forEach(x=>x.addEventListener('change',()=>{const later=document.querySelector('input[name="time"]:checked').value==='later';document.getElementById('schedule-field').hidden=!later;document.getElementById('schedule').required=later}));document.getElementById('checkout-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const schedule=f.elements.schedule;if(f.elements.time.value==='later'&&(!schedule.value||new Date(schedule.value)<=new Date())){toast('یک زمان در آینده انتخاب کن');schedule.focus();return}state.order={number:String(Date.now()).slice(-6),total:sum()+(state.mode==='delivery'?35000:0),count:count(),branch:state.branch.name,branchId:state.branch.id,mode:state.mode,items:JSON.parse(JSON.stringify(state.cart)),timing:f.elements.time.value==='later'?f.elements.schedule.value:'soon'};sessionStorage.setItem('abibiOrder',JSON.stringify(state.order));state.checkoutDraft={};state.cart=[];save();go('success')})}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t){if(e.target.classList.contains('modal-overlay'))closeModal();return}const a=t.dataset.action,id=Number(t.dataset.id);if(a==='pauseSlider'){sliderPaused=!sliderPaused;changeSlide(state.slide)}if(a==='reorder'){if(count()){toast('اول سبد فعلی را تکمیل یا خالی کن');return}state.branch=branches.find(x=>x.id===state.order.branchId)||state.branch;state.cart=JSON.parse(JSON.stringify(state.order.items));save();go('cart');toast('غذاهای سفارش قبلی به سبد اضافه شدند')}if(a==='go')go(t.dataset.page);if(a==='branch')selectBranch(id);if(a==='confirmBranch'){state.cart=[];state.branch=branches.find(b=>b.id===id);save();go('home')}if(a==='mode'){if(state.page==='checkout'){const values=Array.from(document.querySelectorAll('#checkout-form input,#checkout-form textarea')).filter(x=>!['radio','checkbox'].includes(x.type)).map(x=>[x.name,x.value]);setMode(t.dataset.mode);values.forEach(([n,v])=>{let x=document.querySelector(`[name="${n}"]`);if(x)x.value=v})}else setMode(t.dataset.mode)}if(a==='cat'){state.cat=t.dataset.cat;state.query='';go('menu')}if(a==='add')add(id);if(a==='minus'){let i=state.cart.findIndex(x=>x.id===id);if(i>=0){state.cart[i].qty--;state.cart=state.cart.filter(x=>x.qty>0);save();render()}}if(a==='qty'){state.cart[id].qty+=Number(t.dataset.delta);state.cart=state.cart.filter(x=>x.qty>0);save();render()}if(a==='remove'){state.cart.splice(id,1);save();render()}if(a==='fav'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];localStorage.setItem('abibiFav',JSON.stringify(state.favorites));render()}if(a==='detail')detail(id);if(a==='detailAdd'){const extra=document.getElementById('extra-cheese').checked?45000:0,note=document.getElementById('food-note').value.trim();closeModal();add(id,extra,note)}if(a==='close')closeModal();if(a==='slide')changeSlide(id);if(a==='nextslide')changeSlide(state.slide+1);if(a==='prevslide')changeSlide(state.slide-1);if(a==='login'){openModal(`<div class="modal-small"><h2>ورود به آبی‌بی</h2><p>این فرم برای نمایش طراحی است؛ کدی ارسال نمی‌شود.</p><form id="demo-login"><div class="field"><label for="login-phone">شماره موبایل</label><input id="login-phone" required type="tel" inputmode="tel" pattern="[0-9۰-۹٠-٩]{11}" placeholder="۰۹۱۲۳۴۵۶۷۸۹"></div><button class="btn full" type="submit">مشاهده مرحله بعد</button></form></div>`);document.getElementById('demo-login').onsubmit=e=>{e.preventDefault();openModal(`<div class="modal-small"><h2>تأیید شماره موبایل</h2><p>در نسخه نهایی اینجا کد پیامکی وارد می‌شود. برای پیش‌نمایش، ادامه را بزن.</p><div class="field"><input value="۱۲۳۴" readonly aria-label="کد نمونه"></div><button class="btn full" data-action="demoLogin">ادامه نمایشی</button></div>`)}}if(a==='demoLogin'){closeModal();toast('مسیر ورود نمایشی تکمیل شد')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&document.querySelector('.modal-box')){const els=[...document.querySelectorAll('.modal-box button,.modal-box input,.modal-box textarea')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('popstate',()=>go(location.hash.slice(1)||'branches',true));render();setTimeout(()=>{if(state.page==='splash'){const target=location.hash.slice(1);go(state.branch&&['home','menu','cart','checkout','account','orders','success'].includes(target)?target:'branches',true)}},matchMedia('(prefers-reduced-motion: reduce)').matches?500:2100);
